import React, { Component } from "react";
import * as d3 from "d3";
import { select } from "d3-selection";

class BootstrapGraph extends Component {
  componentDidMount() {
    const { data } = this.props;
    this.drawGraph(data, 5);
  }

  kde(kernel, thresholds, data) {
    return thresholds.map(t => [t, d3.mean(data, d => kernel(t - d))]);
  }

  epanechnikov(bandwidth) {
    return x =>
      Math.abs((x /= bandwidth)) <= 1 ? (0.75 * (1 - x * x)) / bandwidth : 0;
  }

  drawGraph(data, bandwidth) {
    const margin = { top: 30, right: 30, bottom: 30, left: 50 };
    const width = 460 - margin.left - margin.right;
    const height = 400 - margin.top - margin.bottom;

    const x = d3
      .scaleLinear()
      .domain(d3.extent(data))
      .nice()
      .range([margin.left, width - margin.right]);

    const thresholds = x.ticks(40);

    const bins = d3
      .histogram()
      .domain(x.domain())
      .thresholds(thresholds)(data);

    const y = d3
      .scaleLinear()
      .domain([0, d3.max(bins, d => d.length) / data.length])
      .range([height - margin.bottom, margin.top]);

    const density = this.kde(this.epanechnikov(bandwidth), thresholds, data);

    const line = d3
      .line()
      .curve(d3.curveBasis)
      .x(d => x(d[0]))
      .y(d => y(d[1]));

    const xAxis = g =>
      g
        .attr("transform", `translate(0,${height - margin.bottom})`)
        .call(d3.axisBottom(x))
        .call(g =>
          g
            .append("text")
            .attr("x", width - margin.right)
            .attr("y", -6)
            .attr("fill", "#000")
            .attr("text-anchor", "end")
            .attr("font-weight", "bold")
        );

    const yAxis = g =>
      g
        .attr("transform", `translate(${margin.left},0)`)
        .call(d3.axisLeft(y).ticks(null, "%"))
        .call(g => g.select(".domain").remove());

    const svg = d3
      .select(this.refs.bootstrapGraph)
      .append("svg")
      .attr("width", width + margin.left + margin.right)
      .attr("height", height + margin.top + margin.bottom)
      .append("g")
      .attr("transform", "translate(" + margin.left + "," + margin.top + ")")
      .data(bins)
      .join("rect")
      .attr("x", d => x(d.x0) + 1)
      .attr("y", d => y(d.length / data.length))
      .attr("width", d => x(d.x1) - x(d.x0) - 1)
      .attr("height", d => y(0) - y(d.length / data.length));

    svg
      .append("path")
      .datum(density)
      .attr("fill", "none")
      .attr("stroke", "#000")
      .attr("stroke-width", 1.5)
      .attr("stroke-linejoin", "round")
      .attr("d", line);

    svg.append("g").call(xAxis);
    svg.append("g").call(yAxis);
    return svg.node();
  }

  render() {
    return <div ref="bootstrapGraph"></div>;
  }
}

export default BootstrapGraph;

