        else if(this.keyLogger.keyDown['y']){
            // Update stored y transform
            this.transformY = d3.zoomIdentity.translate(0,e.transform['y'])
                .scale(this.transformY['k']*e.transform['k']/this.transformKprev)
            // Reset d3 x transform to stored value
            e.transform['x'] = this.transformX['x']
