        // Zoom both x and y
        else{
            this.transformX = d3.zoomIdentity.translate(e.transform['x'],0)
                .scale(this.transformX['k']*e.transform['k']/this.transformKprev)
            this.transformY = d3.zoomIdentity.translate(0,e.transform['y'])
                .scale(this.transformY['k']*e.transform['k']/this.transformKprev)
        }
        // Update previous scale value
        this.transformKprev = e.transform['k']

        // Update scale
        var xScaleNew = this.transformX.rescaleX(this.xScale)
        var yScaleNew = this.transformY.rescaleY(this.yScale)

